// Score a URL for relevance to a query using keyword matching
function scoreAwUrl(url: string, query: string): number {
  const slug = url.toLowerCase().replace(/https?:\/\/[^/]+\/en\//, '').replace(/[/-]/g, ' ');
  const words = query.toLowerCase().split(/\W+/).filter(w => w.length > 2);
  return words.reduce((score, w) => score + (slug.includes(w) ? 1 : 0), 0);
}

// Pick top N most relevant Arctic Wolf doc URLs for a query
function findAwUrls(query: string, n = 4): string[] {
  return AW_KB_URLS
    .map(url => ({ url, score: scoreAwUrl(url, query) }))
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, n)
    .map(x => x.url);
}

async function fetchAwPage(url: string): Promise<{ title: string; content: string; url: string }> {
  try {
    const res = await directFetch(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BroadPeakPortal/1.0)', Accept: 'text/html' },
      signal: AbortSignal.timeout(8000),
      ...fetchOpts(),
    }) as any;
    if (!res.ok) return { title: '', content: '', url };
    const html = await res.text() as string;
    // Extract title
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    const title = titleMatch ? titleMatch[1].replace(' | Arctic Wolf Documentation', '').trim() : url.split('/').pop() || url;
    // Strip scripts/styles and extract text
    const clean = html
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<nav[\s\S]*?<\/nav>/gi, '')
      .replace(/<header[\s\S]*?<\/header>/gi, '')
      .replace(/<footer[\s\S]*?<\/footer>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/\s+/g, ' ').trim().slice(0, 3000);
    return { title, content: clean, url };
  } catch { return { title: '', content: '', url }; }
}


import { fetch as directFetch, Agent as DirectAgent } from 'undici';
import nodemailer from 'nodemailer';
import db from './db.js';
import { getCustomerByDomain, getAllCustomers, upsertCustomerCache, getCacheStats } from './salesforce.js';
import { verifyPassword, setPassword, generateResetToken, consumeResetToken, verifyTotp, enableTotp, disableTotp, getTotpQR, getTotpStatus, isTotpEnabled } from './auth.js';
import { PRODUCTS, ALL_CATEGORIES, ALL_VENDORS, VENDOR_INFO, findRelevantProducts, getVendorsByCategory } from './vendors.js';

const router = express.Router();
const agent = new DirectAgent({ connect: { rejectUnauthorized: false } });
const fetchOpts = () => ({ dispatcher: agent } as any);

// ── File storage ─────────────────────────────────────────────
const DATA_DIR = process.env.DATA_DIR || path.join(process.cwd(), 'data');
const UPLOADS_DIR = path.join(DATA_DIR, 'uploads');
if (!fs.existsSync(UPLOADS_DIR)) fs.mkdirSync(UPLOADS_DIR, { recursive: true });

const storage = multer.diskStorage({
  destination: UPLOADS_DIR,
  filename: (_, file, cb) => cb(null, `${Date.now()}-${file.originalname}`),
});
const upload = multer({ storage, limits: { fileSize: 50 * 1024 * 1024 } });

// ── Auth constants ────────────────────────────────────────────
const CUSTOMER_PASSWORD = process.env.CUSTOMER_PASSWORD || 'Setup187!!';
const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD || 'BPAdmin2024!';

// ── Customer login ────────────────────────────────────────────
router.post('/api/login', async (req, res) => {
  const { domain, password, totpCode } = req.body;
  if (!domain || !password) return res.status(400).json({ error: 'Missing domain or password' });
  const passwordOk = await verifyPassword(domain.toLowerCase().trim(), password);
  if (!passwordOk) return res.status(401).json({ error: 'Invalid credentials' });

  // If 2FA is enabled for this domain, check TOTP before issuing token
  const cleanDomainForTotp = domain.toLowerCase().trim().replace(/^www\./, '');
  if (isTotpEnabled(cleanDomainForTotp)) {
    if (!totpCode) return res.status(202).json({ requires2FA: true });
    if (!verifyTotp(cleanDomainForTotp, String(totpCode))) {
      return res.status(401).json({ error: 'Invalid authenticator code' });
    }
  }

  // Strip any @ prefix
  const cleanDomain = domain.replace(/^@/, '').toLowerCase().trim();

  try {
    const customer = await getCustomerByDomain(cleanDomain);
    if (!customer) return res.status(401).json({ error: 'No account found for this domain. Please contact your Broad Peak account manager.' });

    const token = `cust_${uuid()}`;
    res.json({
      token,
      domain: customer.domain,
      accountName: customer.accountName,
    });
  } catch (err: any) {
    console.error('Login error:', err);
    res.status(500).json({ error: 'Authentication error' });
  }
});

// ── Admin login ───────────────────────────────────────────────
router.post('/api/admin/login', (req, res) => {
  const { password } = req.body;
  if (password !== ADMIN_PASSWORD) return res.status(401).json({ error: 'Invalid admin password' });
  const token = `admin_${uuid()}`;
  db.prepare('INSERT INTO admin_sessions (token, created_at) VALUES (?, ?)').run(token, new Date().toISOString());
  res.json({ token });
});

function requireAuth(req: any, res: any, next: any) {
  const auth = req.headers.authorization || '';
  const token = auth.replace('Bearer ', '');
  if (!token.startsWith('cust_') && !token.startsWith('admin_')) return res.status(401).json({ error: 'Unauthorised' });
  next();
}

function requireAdmin(req: any, res: any, next: any) {
  const auth = req.headers.authorization || '';
  const token = auth.replace('Bearer ', '');
  if (!token.startsWith('admin_')) return res.status(401).json({ error: 'Unauthorised' });
  const row = db.prepare('SELECT token FROM admin_sessions WHERE token = ?').get(token);
  if (!row) return res.status(401).json({ error: 'Unauthorised' });
  next();
}

// ── Admin: seed Salesforce cache ──────────────────────────────
const SEED_SECRET = process.env.SEED_SECRET || 'bpseed2026';

router.post('/api/admin/seed-sf', async (req, res) => {
  const auth = req.headers['x-seed-secret'] || '';
  if (auth !== SEED_SECRET) return res.status(401).json({ error: 'Unauthorised' });
  try {
    const { records } = req.body;
    if (!Array.isArray(records) || records.length === 0) return res.status(400).json({ error: 'No records provided' });
    upsertCustomerCache(records);
    const stats = getCacheStats();
    res.json({ ok: true, inserted: records.length, total: stats.count, lastUpdated: stats.lastUpdated });
  } catch (err: any) {
    console.error('Seed error:', err);
    res.status(500).json({ error: err.message });
  }
});

router.get('/api/admin/cache-stats', (req, res) => {
  try { res.json(getCacheStats()); } catch (err: any) { res.status(500).json({ error: err.message }); }
});

// ── Account Manager management ────────────────────────────────
const amMediaStorage = multer.diskStorage({
  destination: UPLOADS_DIR,
  filename: (_, file, cb) => {
    const ext = path.extname(file.originalname);
    cb(null, `am-${Date.now()}${ext}`);
  },
});
const amMediaUpload = multer({ storage: amMediaStorage, limits: { fileSize: 200 * 1024 * 1024 } }); // 200MB for video

function amToResponse(am: any) {
  return {
    ...am,
    photo_url: am.photo_path ? `/uploads/${path.basename(am.photo_path)}` : null,
    welcome_video_url: am.welcome_video_path ? `/uploads/${path.basename(am.welcome_video_path)}` : null,
  };
}

router.get('/api/admin/account-managers', requireAdmin, (req, res) => {
  const rows = db.prepare('SELECT * FROM account_managers ORDER BY name ASC').all() as any[];
  res.json(rows.map(amToResponse));
});

// Create or update (upsert) — handles photo upload
router.post('/api/admin/account-managers', requireAdmin, amMediaUpload.single('photo'), (req, res) => {
  const { email, name, display_name, phone, calendly } = req.body;
  if (!email || !name) return res.status(400).json({ error: 'email and name required' });
  const photo_path = (req as any).file?.path || null;
  const now = new Date().toISOString();
  const existing = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(email) as any;
  if (existing) {
    const newPhoto = photo_path || existing.photo_path;
    db.prepare(`UPDATE account_managers SET name=?, display_name=?, phone=?, photo_path=?, calendly=?, updated_at=? WHERE email=?`)
      .run(name, display_name || name, phone || null, newPhoto, calendly || null, now, email);
  } else {
    db.prepare(`INSERT INTO account_managers (email, name, display_name, phone, photo_path, calendly, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)`)
      .run(email, name, display_name || name, phone || null, photo_path, calendly || null, now);
  }
  const row = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(email) as any;
  res.json(amToResponse(row));
});

// PATCH — partial edit (name, phone, calendly, display_name only — no files)
router.patch('/api/admin/account-managers/:email', requireAdmin, (req, res) => {
  const email = decodeURIComponent(req.params.email);
  const existing = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(email) as any;
  if (!existing) return res.status(404).json({ error: 'Not found' });
  const { name, display_name, phone, calendly } = req.body;
  const now = new Date().toISOString();
  db.prepare(`UPDATE account_managers SET name=?, display_name=?, phone=?, calendly=?, updated_at=? WHERE email=?`)
    .run(
      name ?? existing.name,
      display_name ?? existing.display_name,
      phone !== undefined ? (phone || null) : existing.phone,
      calendly !== undefined ? (calendly || null) : existing.calendly,
      now, email
    );
  const row = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(email) as any;
  res.json(amToResponse(row));
});

// Upload / replace welcome video for an account manager
router.post('/api/admin/account-managers/:email/video', requireAdmin, amMediaUpload.single('video'), (req, res) => {
  const email = decodeURIComponent(req.params.email);
  const existing = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(email) as any;
  if (!existing) return res.status(404).json({ error: 'Account manager not found. Save the profile first.' });
  if (!(req as any).file) return res.status(400).json({ error: 'No video file provided' });
  // Delete old video file if present
  if (existing.welcome_video_path && fs.existsSync(existing.welcome_video_path)) {
    try { fs.unlinkSync(existing.welcome_video_path); } catch {}
  }
  const video_path = (req as any).file.path;
  db.prepare('UPDATE account_managers SET welcome_video_path=?, updated_at=? WHERE email=?')
    .run(video_path, new Date().toISOString(), email);
  const row = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(email) as any;
  res.json(amToResponse(row));
});

// DELETE welcome video only
router.delete('/api/admin/account-managers/:email/video', requireAdmin, (req, res) => {
  const email = decodeURIComponent(req.params.email);
  const existing = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(email) as any;
  if (!existing) return res.status(404).json({ error: 'Not found' });
  if (existing.welcome_video_path && fs.existsSync(existing.welcome_video_path)) {
    try { fs.unlinkSync(existing.welcome_video_path); } catch {}
  }
  db.prepare('UPDATE account_managers SET welcome_video_path=NULL, updated_at=? WHERE email=?')
    .run(new Date().toISOString(), email);
  res.json({ ok: true });
});

router.delete('/api/admin/account-managers/:email', requireAdmin, (req, res) => {
  db.prepare('DELETE FROM account_managers WHERE email = ?').run(decodeURIComponent(req.params.email));
  res.json({ ok: true });
});

