router.get('/api/customer/:domain', async (req, res) => {
  const { domain } = req.params;
  try {
    const customer = await getCustomerByDomain(domain);
    if (!customer) return res.status(404).json({ error: 'Customer not found' });

    // Enrich account owner with live profile from DB
    let accountOwner = customer.accountOwner;
    if (accountOwner?.email) {
      const amRow = db.prepare('SELECT * FROM account_managers WHERE email = ?').get(accountOwner.email) as any;
      if (amRow) {
        accountOwner = {
          name: amRow.display_name || amRow.name,
          email: amRow.email,
          phone: amRow.phone || '',
          photo: amRow.photo_path ? `/uploads/${path.basename(amRow.photo_path)}` : '',
          calendly: amRow.calendly || '',
          welcome_video: amRow.welcome_video_path ? `/uploads/${path.basename(amRow.welcome_video_path)}` : null,
        };
      }
    }

    res.json({
      accountName: customer.accountName,
      domain: customer.domain,
      grid: customer.grid,
      accountOwner,
    });
  } catch (err: any) {
    console.error('Customer data error:', err);
    res.status(500).json({ error: 'Failed to load customer data' });
  }
});

// ── Translation helper (Arabic → English via Groq) ──────────
async function translateToEnglish(text: string, apiKey: string): Promise<string> {
  try {
    const r = await directFetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        max_tokens: 500,
        stream: false,
        messages: [
          { role: 'system', content: 'You are a professional translator. Translate the following Arabic text to English. Output only the translated text — no explanations, no preamble.' },
          { role: 'user', content: text },
        ],
      }),
      ...fetchOpts(),
    }) as any;
    if (!r.ok) return text; // fallback: use original
    const data: any = await r.json();
    return data.choices?.[0]?.message?.content?.trim() || text;
  } catch { return text; }
}

