function scoreVantaUrl(url: string, query: string): number {
  const slug = url.toLowerCase()
    .replace('https://help.vanta.com/en/articles/', '')
    .replace('https://help.vanta.com/en/collections/', '')
    .replace(/[^a-z0-9]+/g, ' ');
  const words = query.toLowerCase().split(/\W+/).filter(w => w.length > 2);
  return words.reduce((score, w) => score + (slug.includes(w) ? 1 : 0), 0);
}

function findVantaUrls(query: string, n = 4): string[] {
  return VANTA_KB_URLS
    .map(url => ({ url, score: scoreVantaUrl(url, query) }))
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, n)
    .map(x => x.url);
}

async function fetchVantaPage(url: string): Promise<{ title: string; content: string; url: string }> {
  try {
    const res = await directFetch(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BroadPeakPortal/1.0)', Accept: 'text/html' },
      signal: AbortSignal.timeout(8000),
      ...fetchOpts(),
    }) as any;
    if (!res.ok) return { title: '', content: '', url };
    const html = await res.text() as string;
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    const title = titleMatch ? titleMatch[1].replace(/\s*\|.*$/, '').replace(/Vanta$/i, '').trim() || url.split('/').pop() || url : url.split('/').pop() || url;
    const clean = html
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<nav[\s\S]*?<\/nav>/gi, '')
      .replace(/<header[\s\S]*?<\/header>/gi, '')
      .replace(/<footer[\s\S]*?<\/footer>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/\s+/g, ' ').trim().slice(0, 3000);
    return { title, content: clean, url };
  } catch { return { title: '', content: '', url }; }
}

