// POST /api/auth/forgot-password — send reset email
router.post('/api/auth/forgot-password', async (req, res) => {
  const { domain } = req.body;
  if (!domain) return res.status(400).json({ error: 'Missing domain' });
  const cleanDomain = domain.toLowerCase().trim().replace(/^www\./, '');

  // Verify the domain exists
  try {
    const customer = await getCustomerByDomain(cleanDomain);
    if (!customer) {
      // Don't reveal whether domain exists — always return ok
      return res.json({ ok: true });
    }

    const token = generateResetToken(cleanDomain);
    const resetUrl = `${process.env.PORTAL_URL || 'https://portal.broadpeakcyber.com'}/#/reset-password?token=${token}`;

    // Send email via Outlook (using directFetch to M365 Graph if available, else log)
    // For now, prepare the email content — frontend will handle display
    const emailBody = `
Hello,

A password reset was requested for your Broad Peak Customer Portal account (${cleanDomain}).

Click the link below to reset your password. This link expires in 30 minutes.

${resetUrl}

If you did not request this, please ignore this email or contact support@broadpeakcyber.com.

Best regards,
Broad Peak Cyber Team
    `.trim();

    // Send via Outlook connector if available
    try {
      const { sendOutlookEmail } = await import('./email.js').catch(() => ({ sendOutlookEmail: null }));
      if (sendOutlookEmail) {
        await (sendOutlookEmail as any)(
          'support@broadpeakcyber.com',
          `portal@${cleanDomain}`,
          'Broad Peak Portal — Password Reset',
          emailBody
        );
      }
    } catch { /* email optional */ }

    res.json({ ok: true, resetUrl }); // Include URL in response so we can show it if email fails
  } catch {
    res.json({ ok: true }); // Always return ok
  }
});

// POST /api/auth/reset-password — consume token and set new password
router.post('/api/auth/reset-password', async (req, res) => {
  const { token, newPassword } = req.body;
  if (!token || !newPassword) return res.status(400).json({ error: 'Missing token or password' });
  if (newPassword.length < 8) return res.status(400).json({ error: 'Password must be at least 8 characters' });
  const ok = await consumeResetToken(token, newPassword);
  if (!ok) return res.status(400).json({ error: 'Invalid or expired reset link. Please request a new one.' });
  res.json({ ok: true });
});

// POST /api/auth/change-password — change password while logged in
router.post('/api/auth/change-password', requireAuth, async (req, res) => {
  const { domain, currentPassword, newPassword } = req.body;
  if (!domain || !currentPassword || !newPassword) return res.status(400).json({ error: 'Missing fields' });
  if (newPassword.length < 8) return res.status(400).json({ error: 'Password must be at least 8 characters' });
  const cleanDomain = domain.toLowerCase().trim();
  const ok = await verifyPassword(cleanDomain, currentPassword);
  if (!ok) return res.status(401).json({ error: 'Current password is incorrect' });
  await setPassword(cleanDomain, newPassword);
  res.json({ ok: true });
});

// GET /api/auth/2fa-status — get 2FA status for domain
router.get('/api/auth/2fa-status', requireAuth, (req, res) => {
  const domain = String(req.query.domain || '').toLowerCase().trim();
  if (!domain) return res.status(400).json({ error: 'Missing domain' });
  const status = getTotpStatus(domain);
  res.json(status);
});

// POST /api/auth/2fa-setup — generate TOTP secret + QR code
router.post('/api/auth/2fa-setup', requireAuth, async (req, res) => {
  const { domain } = req.body;
  if (!domain) return res.status(400).json({ error: 'Missing domain' });
  const cleanDomain = domain.toLowerCase().trim();
  try {
    const { secret, qrDataUrl } = await getTotpQR(cleanDomain);
    res.json({ ok: true, secret, qrDataUrl });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/auth/2fa-enable — verify code then enable 2FA
router.post('/api/auth/2fa-enable', requireAuth, (req, res) => {
  const { domain, code } = req.body;
  if (!domain || !code) return res.status(400).json({ error: 'Missing domain or code' });
  const ok = enableTotp(domain.toLowerCase().trim(), String(code));
  if (!ok) return res.status(400).json({ error: 'Invalid code — please try again' });
  res.json({ ok: true });
});

// POST /api/auth/2fa-disable — disable 2FA (requires current TOTP or password)
router.post('/api/auth/2fa-disable', requireAuth, async (req, res) => {
  const { domain, code, password } = req.body;
  if (!domain) return res.status(400).json({ error: 'Missing domain' });
  const cleanDomain = domain.toLowerCase().trim();

  // Verify either a valid TOTP code or current password
  let verified = false;
  if (code) verified = verifyTotp(cleanDomain, String(code));
  if (!verified && password) verified = await verifyPassword(cleanDomain, password);
  if (!verified) return res.status(401).json({ error: 'Please provide a valid authenticator code or your current password' });

  disableTotp(cleanDomain);
  res.json({ ok: true });
});

// ─── FRESHDESK TICKET ────────────────────────────────────────────────────────
router.post('/api/support-ticket', async (req, res) => {
  const { subject, description, customerEmail, customerName, accountName, resolved } = req.body;
  const FRESHDESK_API_KEY = process.env.FRESHDESK_API_KEY || '';
  const FRESHDESK_DOMAIN = process.env.FRESHDESK_DOMAIN || '';

  if (!FRESHDESK_API_KEY || !FRESHDESK_DOMAIN) {
    // Log it server-side even without Freshdesk configured
    console.log(`[TICKET] ${resolved ? 'RESOLVED' : 'OPEN'} — ${accountName} — ${subject}`);
    return res.json({ ok: true, simulated: true, message: 'Ticket logged (Freshdesk not yet configured)' });
  }

  try {
    const ticketBody = {
      subject,
      description,
      email: customerEmail || `support@${req.body.domain || 'unknown'}.com`,
      name: customerName || accountName,
      priority: 2,
      status: resolved ? 4 : 2, // 4 = resolved, 2 = open
      tags: ['portal', 'ai-support', resolved ? 'self-resolved' : 'human-requested'],
      custom_fields: { account_name: accountName },
    };
    const fdRes = await directFetch(`https://${FRESHDESK_DOMAIN}.freshdesk.com/api/v2/tickets`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Basic ${Buffer.from(`${FRESHDESK_API_KEY}:X`).toString('base64')}`,
      },
      body: JSON.stringify(ticketBody),
      ...fetchOpts(),
    }) as any;
    const data = await fdRes.json() as any;
    res.json({ ok: fdRes.ok, ticketId: data.id, status: data.status });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ─── FRESHDESK — list tickets for a customer domain ───────────────────────
const FD_KEY = process.env.FRESHDESK_API_KEY || 'JskX8UIRV8c65RQtaTUf';
const FD_DOMAIN = process.env.FRESHDESK_DOMAIN || 'broadpeakcyber';
const FD_AUTH = Buffer.from(`${FD_KEY}:X`).toString('base64');

const FD_STATUS: Record<number,string> = {1:'Open',2:'Pending',3:'Resolved',4:'Closed',5:'Waiting on Customer',6:'Waiting on Third Party'};
const FD_PRIORITY: Record<number,string> = {1:'Low',2:'Medium',3:'High',4:'Urgent'};

// GET /api/tickets?domain=gigglingsquid.com  — returns tickets whose requester email domain matches
router.get('/api/tickets', requireAuth, async (req, res) => {
  const domain = (req.query.domain as string || '').toLowerCase().trim();
  if (!domain) return res.status(400).json({ ok: false, error: 'domain required' });
  try {
    // Fetch all tickets newest-first (up to 100; most portals will have far fewer per account)
    const pages: any[] = [];
    for (let page = 1; page <= 5; page++) {
      const r = await directFetch(
        `https://${FD_DOMAIN}.freshdesk.com/api/v2/tickets?order_type=desc&order_by=created_at&per_page=100&page=${page}&include=requester`,
        { headers: { Authorization: `Basic ${FD_AUTH}`, 'Content-Type': 'application/json' }, ...fetchOpts() }
      ) as any;
      if (!r.ok) break;
      const batch: any[] = await r.json();
      if (!batch.length) break;
      pages.push(...batch);
      if (batch.length < 100) break;
    }
    // Filter: match requester email domain, or subject/tags contain the domain
    // Exclude Barracuda phishing alert auto-tickets (per user instruction)
    const PHISHING_SENDERS = ['noreply@barracuda.com', 'phishing@barracuda.com', 'alerts@barracuda.com'];
    const matched = pages.filter(t => {
      const reqEmail: string = (t.requester?.email || '').toLowerCase();
      // Exclude Barracuda phishing alerts
      if (PHISHING_SENDERS.includes(reqEmail)) return false;
      if ((t.subject || '').toLowerCase().includes('targeted phishing attack detected')) return false;
      if ((t.subject || '').toLowerCase().includes('phishing alert')) return false;
      const reqDomain = reqEmail.includes('@') ? reqEmail.split('@')[1].toLowerCase() : '';
      return reqDomain === domain ||
        (t.subject || '').toLowerCase().includes(domain) ||
        (t.tags || []).some((tag: string) => tag.toLowerCase().includes(domain));
    });
    const tickets = matched.map(t => ({
      id: t.id,
      subject: t.subject,
      status: FD_STATUS[t.status] || String(t.status),
      statusCode: t.status,
      priority: FD_PRIORITY[t.priority] || String(t.priority),
      priorityCode: t.priority,
      createdAt: t.created_at,
      updatedAt: t.updated_at,
      requesterName: t.requester?.name || '',
      requesterEmail: t.requester?.email || '',
      type: t.type || null,
      tags: t.tags || [],
    }));
    res.json({ ok: true, tickets });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/tickets — create ticket in Freshdesk via API
// Freshdesk will notify the team per its own notification rules.
// The requester email is set to portal@<domain> so Freshdesk associates it with the right account.
router.post('/api/tickets', requireAuth, async (req, res) => {
  const { subject, description, priority, type, domain, customerName, lang } = req.body;
  if (!subject || !description) return res.status(400).json({ ok: false, error: 'subject and description required' });
  try {
    const OPENAI_KEY = process.env.OPENAI_API_KEY || '';

    // If submitted in Arabic, translate to English for the Broad Peak team
    // Keep the original Arabic text appended so context is not lost
    let finalSubject = subject;
    let finalDescription = description;
    if (lang === 'ar') {
      const [translatedSubject, translatedDescription] = await Promise.all([
        translateToEnglish(subject, OPENAI_KEY),
        translateToEnglish(description, OPENAI_KEY),
      ]);
      finalSubject = translatedSubject;
      finalDescription = `${translatedDescription}\n\n---\n[Original Arabic / النص الأصلي بالعربية]\n${description}`;
    }

    const customerEmail = `portal@${domain || 'customer.com'}`;
    const senderName = customerName || `Portal User (${domain})`;

    const ticketBody = {
      subject: finalSubject,
      description: finalDescription,
      email: customerEmail,
      name: senderName,
      priority: priority || 2,
      status: 2,
      type: type || null,
      tags: ['portal', domain || 'unknown'],
    };

    const r = await directFetch(`https://${FD_DOMAIN}.freshdesk.com/api/v2/tickets`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Basic ${FD_AUTH}` },
      body: JSON.stringify(ticketBody),
      ...fetchOpts(),
    }) as any;
    const data: any = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: data.description || 'Freshdesk error', details: data });

    res.json({
      ok: true,
      ticketId: data.id,
      ticket: {
        id: data.id,
        subject: data.subject,
        status: FD_STATUS[data.status] || String(data.status),
        statusCode: data.status,
        priority: FD_PRIORITY[data.priority] || String(data.priority),
        priorityCode: data.priority,
        createdAt: data.created_at,
        updatedAt: data.updated_at,
        requesterName: senderName,
        requesterEmail: customerEmail,
        type: data.type || null,
        tags: data.tags || [],
      },
    });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

export default router;
